import json
import os
from pathlib import Path

import jax
import jax.numpy as jnp
import numpy as np


def basic_reduce(x):
    return jnp.mean(x, axis=1)


def map_square(x):
    return jnp.square(x)


def grad_logistic(x, y, w):
    def loss_fn(w_):
        logits = x @ w_
        return jnp.mean(jnp.log1p(jnp.exp(-y * logits)))

    return jax.grad(loss_fn)(w)


def scan_rnn(seq, init, Wx, Wh, b):
    def step(h, x_t):
        h_next = jnp.tanh(Wx @ x_t + Wh @ h + b)
        return h_next, h_next

    _, hs = jax.lax.scan(step, init, seq)
    return hs


def jit_mlp(X, W1, b1, W2, b2):
    @jax.jit
    def mlp(x, w1, b1_, w2, b2_):
        hidden = jnp.maximum(0, x @ w1 + b1_)
        return hidden @ w2 + b2_

    return mlp(X, W1, b1, W2, b2)


TASK_FUNCS = {
    "basic_reduce": lambda inp: basic_reduce(jnp.array(inp)),
    "map_square": lambda inp: map_square(jnp.array(inp)),
    "grad_logistic": lambda inp: grad_logistic(jnp.array(inp["x"]), jnp.array(inp["y"]), jnp.array(inp["w"])),
    "scan_rnn": lambda inp: scan_rnn(
        jnp.array(inp["seq"]),
        jnp.array(inp["init"]),
        jnp.array(inp["Wx"]),
        jnp.array(inp["Wh"]),
        jnp.array(inp["b"]),
    ),
    "jit_mlp": lambda inp: jit_mlp(
        jnp.array(inp["X"]),
        jnp.array(inp["W1"]),
        jnp.array(inp["b1"]),
        jnp.array(inp["W2"]),
        jnp.array(inp["b2"]),
    ),
}


def load_input(path):
    if path.endswith(".npy"):
        return np.load(path)
    if path.endswith(".npz"):
        return np.load(path)
    raise ValueError(f"Unsupported input format: {path}")


def main():
    with open("/app/problem.json", "r", encoding="utf-8") as f:
        tasks = json.load(f)

    for task in tasks:
        task_id = task["id"]
        input_path = os.path.join("/app", task["input"])
        output_path = os.path.join("/app", task["output"])

        if task_id not in TASK_FUNCS:
            raise KeyError(f"No handler for task id: {task_id}")

        inp = load_input(input_path)
        result = TASK_FUNCS[task_id](inp)

        Path(os.path.dirname(output_path) or ".").mkdir(parents=True, exist_ok=True)
        np.save(output_path, np.array(result, dtype=np.float32))


if __name__ == "__main__":
    main()
